'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {downloadReport,reportUsd} from '@/lib/report-export';
import {paymentMethods,paymentEvidence,paymentPeriod,paymentAddDays,paymentSourceLabel,paymentStatusLabel,paymentClassificationLabel,paymentReportCsv,validatePaymentReport,type PaymentReport,type PaymentReportScope,type PaymentRow,type PaymentPurposeTotals} from '@/lib/payment-record-reviews';

type Props=PaymentReportScope&{businessDate:string;disabled?:boolean;reviewRevision?:number;onOpen:(reservation:string,entry:string)=>void};
const countLabels={unreviewed:'Method not reviewed',reviewed_external_record:'External evidence reviewed by operator',reviewed_operator_report:'Operator statement only',reviewed_insufficient_evidence:'Reviewed: insufficient evidence',original_deposit_method:'Method reported on deposit record',not_money_movement:'Record reductions; no money movement'};
export function PaymentActivityReport(props:Props){return <Activity key={[props.actor,props.tenant,props.property].join('/')} {...props}/>}
function Activity({actor,tenant,property,businessDate,disabled=false,reviewRevision=0,onOpen}:Props){
 const [initialReviewRevision]=useState(reviewRevision);
 const [initialStart]=useState(paymentAddDays(businessDate,-6)),[initialEnd]=useState(paymentAddDays(businessDate,1)),[start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[data,setData]=useState<PaymentReport|null>(null),[loaded,setLoaded]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState(''),[revision,setRevision]=useState(0);
 const control=useRef({alive:true,sequence:0,locked:false});
 const scopeKey=[actor,tenant,property].join('/'),selectedKey=scopeKey+'/'+start+'/'+end+'/'+reviewRevision;
 const read=useCallback(async(from:string,until:string)=>{if(!paymentPeriod(from,until))throw Error('Choose 1–366 recording dates with an exclusive end after the start.');const value=await hotelRpc<unknown>('cashier_activity_report',{p_tenant:tenant,p_property:property,p_start:from,p_end:until});validatePaymentReport(value,{actor,tenant,property},from,until);return value},[actor,tenant,property]);
 useEffect(()=>{const current=control.current;current.alive=true;const seq=++current.sequence;void read(initialStart,initialEnd).then(value=>{if(current.alive&&seq===current.sequence){setData(value);setLoaded(scopeKey+'/'+initialStart+'/'+initialEnd+'/'+initialReviewRevision);setLoading(false);setRevision(n=>n+1)}}).catch(()=>{if(current.alive&&seq===current.sequence){setError('The selected payment activity could not be verified. Try a narrower recording period or refresh.');setLoading(false)}});return()=>{current.alive=false;current.sequence++}},[read,initialStart,initialEnd,scopeKey,initialReviewRevision]);
 async function refresh(){const current=control.current;if(disabled||current.locked)return;current.locked=true;const seq=++current.sequence;setLoading(true);setLoaded('');setError('');try{const value=await read(start,end);if(current.alive&&seq===current.sequence){setData(value);setLoaded(selectedKey);setRevision(n=>n+1)}}catch{if(current.alive&&seq===current.sequence)setError(paymentPeriod(start,end)?'The selected payment activity could not be verified. Try a narrower recording period or refresh.':'Choose 1–366 recording dates with an exclusive end after the start.')}finally{current.locked=false;if(current.alive&&seq===current.sequence)setLoading(false)}}
 const fresh=!!data&&loaded===selectedKey&&!loading&&!error&&!disabled;
 function exportCsv(){if(!fresh||!data)return;try{downloadReport('recorded-payment-activity-'+start+'-'+end,paymentReportCsv(data))}catch{setLoaded('');setError('This prepared report could not be exported. Refresh before trying again.')}}
 return <section className="card pilot-reports pilot-payment-activity"><style>{'.pilot-payment-activity .pilot-actions{flex-wrap:wrap}.pilot-payment-activity .pilot-actions .primary{font-size:14px}.pilot-payment-activity .payment-record-text{white-space:pre-wrap;overflow-wrap:anywhere}.pilot-payment-activity>h3,.pilot-payment-activity>p,.pilot-payment-activity>details{margin-left:24px;margin-right:24px}.pilot-payment-activity h3{font-size:16px;font-weight:600;margin-bottom:8px}.pilot-payment-activity .payment-purpose{padding:24px;margin-top:20px;border-top:1px solid #dce3ee}.pilot-payment-activity details{margin-top:10px;margin-bottom:10px}'}</style><div className="section-top"><div><h2>Recorded payment activity</h2><p>External payment records by original recording time, with the latest method review.</p></div><button className="secondary" disabled={!fresh} onClick={exportCsv}>Export recorded activity CSV</button></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void refresh()}}><label className="field">Recording date from<input type="date" required value={start} disabled={loading||disabled} onChange={e=>setStart(e.target.value)}/></label><label className="field">Recording date until (exclusive)<input type="date" required value={end} disabled={loading||disabled} onChange={e=>setEnd(e.target.value)}/></label><button className="primary" disabled={loading||disabled}>{loading?'Loading…':'Load payment activity'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}
 {!fresh||!data?<output className="pilot-empty">{loading?'Loading the selected recording period…':'Load the selected period before viewing or exporting.'}</output>:<><h3>{data.property.name}</h3><p>{data.period.start} through {data.period.end} (end exclusive) · {data.property.time_zone}</p><p>{data.summary.row_count} complete records: {data.summary.folio_row_count} guest-account records and {data.summary.security_deposit_row_count} security-fund records.</p><p>These are external records, not counted cash or verified settlement. The two purposes remain separate; they may contain duplicate descriptions of a real-world transfer. No combined money total is calculated.</p><p>Both sources use their original timestamps in the current property zone for this period. A security book’s stored date/zone is shown separately and may differ from the existing deposit activity report.</p><p>A later review can change a newly prepared report’s method grouping. This is not a historical classification report or a property-wide unresolved queue.</p><details><summary>Prepared period details</summary><p>Prepared {data.generated_at}<br/>UTC start {data.period.start_at}<br/>UTC end {data.period.end_at}</p>{data.property.text_normalized&&<p>The property name was normalized for this display; original financial references remain unchanged.</p>}</details>
 <Purpose key={'folio/'+revision} title="Guest-account external records" purpose="guest_folio" totals={data.totals.guest_folio} rows={data.rows.filter(r=>r.ledger==='folio')} zone={data.property.time_zone} disabled={disabled} onOpen={onOpen}/>
 <Purpose key={'security/'+revision} title="Refundable security-fund records" purpose="refundable_security" totals={data.totals.refundable_security} rows={data.rows.filter(r=>r.ledger==='security_deposit')} zone={data.property.time_zone} disabled={disabled} onOpen={onOpen}/>
 <p className="muted">CSV contains every returned row, both purpose summaries and their method counts. Empty periods show zero selected activity, not a zero account balance or zero held funds.</p></>}
 </section>;
}
function Purpose({title,purpose,totals,rows,zone,disabled,onOpen}:{title:string;purpose:'guest_folio'|'refundable_security';totals:PaymentPurposeTotals;rows:PaymentRow[];zone:string;disabled:boolean;onOpen:Props['onOpen']}){
 const [page,setPage]=useState(0),pageSize=100,pages=Math.max(1,Math.ceil(rows.length/pageSize)),index=Math.min(page,pages-1),visible=rows.slice(index*pageSize,(index+1)*pageSize),balanceLabel=purpose==='guest_folio'?'Recorded-paid effect':'Held-record effect';
 const time=(value:string)=>new Intl.DateTimeFormat('en-US',{timeZone:zone,dateStyle:'medium',timeStyle:'long'}).format(new Date(value));
 return <section className="payment-purpose"><h3>{title}</h3><p>{totals.record_count} records · {totals.external_record_count} external payment/refund records · {totals.reduction_record_count} record reductions.</p><div className="detail-grid"><div>Recorded received<b>{reportUsd(totals.received_minor)}</b></div><div>Recorded refunded<b>{reportUsd(totals.refunded_minor)}</b></div><div>Record reductions<b>{reportUsd(totals.reduced_minor)}</b></div><div>External-record effect<b>{reportUsd(totals.external_record_effect_minor)}</b></div><div>{balanceLabel}<b>{reportUsd(totals.record_balance_effect_minor)}</b></div></div><p>Period effects may be negative when a refund or reduction relates to an earlier period. They are not current balances or approval to refund.</p>
 <div className="pilot-table-wrap"><table className="pilot-table"><caption>{title} by recorded method</caption><thead><tr><th scope="col">Method</th><th scope="col">Records</th><th scope="col">Received</th><th scope="col">Refunded</th><th scope="col">External-record effect</th></tr></thead><tbody>{totals.by_method.map(m=><tr key={m.method}><td>{paymentMethods[m.method]}</td><td>{m.record_count}</td><td>{reportUsd(m.received_minor)}</td><td>{reportUsd(m.refunded_minor)}</td><td>{reportUsd(m.external_record_effect_minor)}</td></tr>)}</tbody></table></div><p>{totals.unknown_method_record_count} external records have an unknown method; their amounts remain in the Unknown row. Record reductions are excluded from method totals.</p><details><summary>Classification counts</summary>{Object.entries(totals.classification_counts).map(([name,count])=><p key={name}>{countLabels[name as keyof typeof countLabels]}: {count}</p>)}</details>
 <div className="pilot-table-wrap"><table className="pilot-table"><caption>{title}: original records and current reviews</caption><thead><tr><th scope="col">Original record</th><th scope="col">Current booking</th><th scope="col">Recorded time</th><th scope="col">Method / evidence</th><th scope="col">Effects</th><th scope="col">Review</th></tr></thead><tbody>{visible.map(row=><tr key={[row.ledger,row.reservation.id,row.record.id].join('/')}><td><strong>{paymentSourceLabel(row.record)}</strong><small>{reportUsd(row.record.amount_minor)}</small><p className="payment-record-text">{row.record.reference}</p><details><summary>Original evidence and audit details</summary><p className="payment-record-text">{row.record.reason}</p><small>Recorded by {row.record.actor_id}<br/>Record {row.record.id}<br/>Request {row.record.request_id}<br/>Reservation {row.reservation.id}<br/>Target {row.ledger==='folio'?row.record.target_entry_id??'None':row.record.target_event_id??'None'}</small></details></td><td className="payment-record-text">{row.reservation.source_booking_id}<small>{row.reservation.source} · {paymentStatusLabel(row.reservation)}</small></td><td>{time(row.record.recorded_at)}<small>Report date {row.report_local_date}</small>{row.ledger==='security_deposit'&&<small>Stored date {row.record.recording_date} · {row.record.recording_time_zone}</small>}</td><td>{row.classification.method!==null&&<strong>{paymentMethods[row.classification.method]}</strong>}<p>{paymentClassificationLabel(row.classification)}</p>{row.classification.state==='reviewed'&&<details><summary>Review evidence</summary><p>{paymentEvidence[row.classification.evidence_basis!]}</p>{row.classification.method_detail&&<p className="payment-record-text">{row.classification.method_detail}</p>}{row.classification.evidence_reference&&<p className="payment-record-text">Evidence reference: {row.classification.evidence_reference}</p>}<p className="payment-record-text">{row.classification.review_reason}</p><p>Reviewed {time(row.classification.reviewed_at!)} · Version {row.classification.review_version}</p><small>Reviewed by {row.classification.reviewed_by}<br/>Review {row.classification.review_id}</small></details>}</td><td>External record: {reportUsd(row.effects.external_record_effect_minor)}<small>{balanceLabel}: {reportUsd(row.effects.record_balance_effect_minor)}</small></td><td>{row.ledger==='folio'&&['external_payment','external_refund'].includes(row.record.kind)?<button className="text-button" disabled={disabled} onClick={()=>onOpen(row.reservation.id,row.record.id)}>Payment record review</button>:<span>{row.classification.state==='not_money_movement'?'Correction record':'Original deposit method'}</span>}</td></tr>)}</tbody></table></div>{rows.length===0?<p>No records for this purpose in the selected period.</p>:<div className="pilot-actions"><button className="secondary" disabled={disabled||index===0} onClick={()=>setPage(n=>Math.max(0,n-1))}>Previous records</button><p>Showing {index*pageSize+1}–{Math.min((index+1)*pageSize,rows.length)} of {rows.length}. Export includes all rows.</p><button className="secondary" disabled={disabled||index>=pages-1} onClick={()=>setPage(n=>n+1)}>Next records</button></div>}</section>;
}
